44	    int
45	    CHAOSPTW::generateRandomMask(int bits_to_change)
46	    {
47	        int mask = 0;
48	        std::uniform_int_distribution<int> bitDist(0, 7);
49	        while (bits_to_change-- > 0) mask |= (1 << bitDist(rng));
50	        return mask;
51	    }
