72	    void
73	    CHAOSPTW::corruptDescriptor(uint8_t *data, unsigned size, Addr desc_addr)
74	    {
75	        if (probability <= 0.0f) return;
76	        // Count every call to the hook once the injector is active, BEFORE any
77	        // gating (first_clock/max_faults/prob). This distinguishes "PTW walk
78	        // happened (hook called)" from "walk happened but prob did not select
79	        // it (numFaultsInjected=0)" — essential to diagnose H7's spurious rate
80	        // when PTW walk density is low (early FS, pre-MMU-on has few walks).
81	        stats->numHooksCalled++;
82	        Cycles cur = Cycles(curTick() >> 0);
83	        if (cur < first_clock) return;
84	        if (last_clock != Cycles(0) && cur > last_clock) return;
85	        if (max_faults != 0 && faults_injected_count >= max_faults) return;
86	
87	        std::uniform_real_distribution<float> dist(0.0f, 1.0f);
88	        if (dist(rng) >= probability) return;
89	        if (size == 0) return;
90	
91	        // H7: ECC corrects single-bit flips; only >=2-bit (uncorrectable) survive.
92	        // clearValidBit (AND ~0x3) is a 2-bit clear -> uncorrectable, bypasses ECC.
93	        // conditionalValidBit is a SINGLE-bit XOR (bit0) -> ECC SHOULD correct it
94	        // (ECC-on -> benign/no spurious; ECC-off -> invalid/spurious). So
95	        // conditionalValidBit must NOT bypass ECC — only clear_valid_bit does.
96	        if (!clear_valid_bit && ptw_ecc && num_bits < 2) {
97	            stats->numBenignFlips++;
98	            return;
99	        }
100	
101	        uint64_t orig = 0;
102	        std::memcpy(&orig, data, size);
103	
104	        if (conditional_valid_bit) {
105	            // P3c: single-bit XOR bit0, ONLY on block descriptors (low2=0b01).
106	            // 0b01 ^ 0b01 = 0b00 (invalid) -> spurious. Single-bit so ECC-on
107	            // corrects it (no spurious), ECC-off leaves it invalid (spurious).
108	            // This is the faithful within-experiment H7 ECC contrast. Non-0b01
109	            // descriptors are skipped (no corruption) so we don't perturb tables.
110	            if (size >= 1 && (data[0] & 0x3) == 0x1) {
111	                data[0] ^= 0x1;
112	            } else {
113	                // Not a block descriptor — skip injection, count as benign (no
114	                // fault manufactured this walk).
115	                stats->numBenignFlips++;
116	                return;
117	            }
118	        } else if (clear_valid_bit) {
119	            // Force-clear descriptor type bits[1:0] (byte 0, low 2 bits) -> 0b00
120	            // (invalid). This RELIABLY manufactures an invalid PTE regardless of
121	            // the original descriptor type (0b01 block / 0b11 table -> 0b00),
122	            // unlike XOR which only invalidates one type. Models D3's transient
123	            // walk-failure (invalid readout -> fault -> retry reads correct value).
124	            if (size >= 1) data[0] &= (uint8_t)~0x3;
125	        } else {
126	            int off = byte_offset;
127	            if (off < 0) {
128	                std::uniform_int_distribution<int> bd(0, (int)size - 1);
129	                off = bd(rng);
130	            }
131	            if (off >= (int)size) off = (int)size - 1;
132	
133	            int mask = fault_mask ? (int)(fault_mask & 0xff)
134	                                  : generateRandomMask(num_bits);
135	            data[off] ^= (uint8_t)mask;
136	        }
137	        uint64_t corr = 0;
138	        std::memcpy(&corr, data, size);
139	
140	        bool became_invalid = (size == 8) ? longDescInvalid(corr)
141	                                          : shortDescInvalid((uint32_t)corr);
142	        stats->numFaultsInjected++;
143	        ++faults_injected_count;
144	        if (became_invalid) stats->numSpuriousFaults++;
145	        else stats->numBenignFlips++;
146	        writeLog(desc_addr, orig, corr, became_invalid);
147	        DPRINTF(CHAOSPTW, "CHAOSPTW: corrupted desc @%#x (%#lx->%#lx) "
148	                "invalid=%d clearValidBit=%d\n", desc_addr, orig, corr,
149	                became_invalid, clear_valid_bit ? 1 : 0);
150	    }
